import java.io.*;
import java.util.*;

public class CF1187G {
    static final int INF = 0x3f3f3f3f;
    ArrayList<Integer>[] adj;
    int n, m;
    int[] pi, dd, bb;
    int[] uu, vv, uv, cost;
    int[] cap;
    int[] qq;
    int head, tail;
    boolean[] inq;

    void init() {
        adj = new ArrayList[n];
        for (int u = 0; u < n; u++)
            adj[u] = new ArrayList<>();
        pi = new int[n];
        dd = new int[n];
        bb = new int[n];
        qq = new int[n + 5];
        inq = new boolean[n];
        uu = new int[m];
        vv = new int[m];
        uv = new int[m];
        cost = new int[m];
        cap = new int[m * 2];
        m = 0;
    }

    void link(int u, int v, int c, int w) {
        int h = m++;
        uu[h] = u;
        vv[h] = v;
        uv[h] = u ^ v;
        cost[h] = w;
        cap[h << 1] = c;
        adj[u].add(h << 1);
        adj[v].add(h << 1 | 1);
    }

    void enqueue(int v) {
        if (inq[v]) return;
        qq[tail++] = v;
        if (tail == qq.length) tail = 0;
        inq[v] = true;
    }

    int dequeue() {
        int u = qq[head++];
        if (head == qq.length) head = 0;
        inq[u] = false;
        return u;
    }

    boolean spfa(int s, int t) {
        Arrays.fill(pi, INF);
        pi[s] = 0;
        head = tail = 0;
        enqueue(s);
        while (head != tail) {
            int u = dequeue();
            int d = dd[u] + 1;
            for (int h_ : adj[u]) {
                if (cap[h_] > 0) {
                    int h = h_ >> 1;
                    int p = pi[u] + ((h_ & 1) == 0 ? cost[h] : -cost[h]);
                    int v = u ^ uv[h];
                    if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                        pi[v] = p;
                        dd[v] = d;
                        bb[v] = h_;
                        enqueue(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    void push1(int s, int t) {
        for (int u = t, h_, h; u != s; u ^= uv[h]) {
            h = (h_ = bb[u]) >> 1;
            cap[h_]--;
            cap[h_ ^ 1]++;
        }
    }

    int edmonds_karp(int s, int t) {
        while (spfa(s, t))
            push1(s, t);
        int flow = 0;
        for (int h = 0; h < m; h++)
            flow += cost[h] * cap[h << 1 | 1];
        return flow;
    }

    void solve() throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        int N = dis.readInt();
        int M = dis.readInt();
        int K = dis.readInt();
        int C = dis.readInt();
        int D = dis.readInt();

        int[] start = new int[K];
        for (int i = 0; i < K; i++)
            start[i] = dis.readInt() - 1;

        ArrayList<Integer>[] graph = new ArrayList[N];
        for (int i = 0; i < N; i++)
            graph[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            int a = dis.readInt() - 1;
            int b = dis.readInt() - 1;
            graph[a].add(b);
            graph[b].add(a);
        }

        int T = N + K + 1;
        n = N * T + 1;
        m = K + (M * 2 * K + N) * (T - 1);
        init();

        for (int i = 0; i < N; i++) {
            for (int s = 0; s < T - 1; s++) {
                int u = i * T + s;
                for (int j : graph[i]) {
                    int v = j * T + s + 1;
                    for (int x = 1; x <= K; x++)
                        link(u, v, 1, C + (x * 2 - 1) * D);
                }
            }
        }

        for (int i = 0; i < N; i++)
            for (int s = 0; s < T - 1; s++) {
                int u = i * T + s, v = u + 1;
                link(u, v, K, i == 0 ? 0 : C);
            }

        for (int h = 0; h < K; h++)
            link(n - 1, start[h] * T, 1, 0);

        System.out.println(edmonds_karp(n - 1, 0 * T + T - 1));
    }

    public static void main(String[] args) throws IOException {
        new CF1187G().solve();
    }
}
